import pytest
from pydantic import ValidationError
from pipeline.schema import SurvivorshipRule, rule_specificity, CanonicalEntity

def _rule(**kw):
    base = dict(id="1", field="*", entityType="*", strategy="escalate", description="d")
    return SurvivorshipRule(**{**base, **kw})

@pytest.mark.parametrize("field,entity_type,expected", [
    ("*", "*", 0),
    ("name", "*", 2),
    ("*", "account", 1),
    ("name", "account", 3),
])
def test_rule_specificity(field, entity_type, expected):
    assert rule_specificity(_rule(field=field, entityType=entity_type)) == expected

def test_prefer_source_without_preferred_source_id_raises():
    with pytest.raises(ValidationError):
        _rule(strategy="prefer_source")

def test_prefer_source_with_preferred_source_id_ok():
    _rule(strategy="prefer_source", preferredSourceId="src-1")  # must not raise

@pytest.mark.parametrize("strategy", ["most_recent", "most_complete", "escalate"])
def test_non_prefer_source_strategies_dont_need_preferred_source_id(strategy):
    _rule(strategy=strategy)  # must not raise

def test_canon_model_rejects_unknown_fields():
    with pytest.raises(ValidationError):
        CanonicalEntity(externalId="1", entityType="account", name="a",
                        normalizedName="a", sourceId="s", bogusField="x")

def test_canon_model_serializes_camel_case_on_the_wire():
    e = CanonicalEntity(externalId="1", entityType="account", name="Acme",
                        normalizedName="acme", sourceId="s")
    dumped = e.model_dump(by_alias=True)
    assert "externalId" in dumped and "external_id" not in dumped

@pytest.mark.parametrize("bad_severity", [0, 5, 1.5, -1])
def test_severity_literal_rejects_out_of_range(bad_severity):
    from pipeline.schema import Conflict
    with pytest.raises(ValidationError):
        Conflict(runId="00000000-0000-0000-0000-000000000000",
                 matchId="00000000-0000-0000-0000-000000000000",
                 field="x", valueA="a", valueB="b",
                 conflictClass="attribute", severity=bad_severity, detectedBy="rule")
```

