import pytest
from agent.graph import should_auto_apply, AUTO_APPLY_CONFIDENCE_THRESHOLD, AUTO_APPLY_MAX_SEVERITY

def test_high_confidence_low_severity_auto_applies():
    assert should_auto_apply(confidence=0.9, severity=1) is True

def test_below_confidence_threshold_never_auto_applies():
    assert should_auto_apply(confidence=AUTO_APPLY_CONFIDENCE_THRESHOLD - 0.01, severity=1) is False

def test_confidence_exactly_at_threshold_auto_applies():
    assert should_auto_apply(confidence=AUTO_APPLY_CONFIDENCE_THRESHOLD, severity=AUTO_APPLY_MAX_SEVERITY) is True

@pytest.mark.parametrize("severity", [3, 4])
def test_severity_above_max_never_auto_applies_even_at_confidence_1(severity):
    assert should_auto_apply(confidence=1.0, severity=severity) is False

def test_severity_exactly_at_max_is_allowed():
    assert should_auto_apply(confidence=1.0, severity=AUTO_APPLY_MAX_SEVERITY) is True
```

